WITH w AS (SELECT mktcode,tgtcode,bizdate,highPx/10000.0 AS px,MAX(highPx/10000.0) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate ROWS BETWEEN 59 PRECEDING AND CURRENT ROW) AS extreme FROM `newzl`.`hsj_stock_hq_basic`) SELECT mktcode,tgtcode,bizdate FROM w WHERE bizdate='2026-04-14' AND px>=extreme;
